import {createEnterprise,enterpriseViews} from './enterprise/ui.js';
import {runtimes,operators,searchVersions} from './version-search.mjs';
import {normalize,sample,closure,pathTo,compare} from './engine.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let documentContext='';
let model=normalize(sample(),'example.cdx.json'),isSample=true,baseline=null,view='overview',query='',licenseFilter='',riskFilter='',page=0,sort='name',focus='',graphMode='all';
const defaultVersionRequest=()=>({kind:'package',name:'lodash',runtime:'python',match:'exact',operator:'lt',target:'4.17.21'});
let versionRequest=defaultVersionRequest(),versionHasRun=true,versionTab='match',versionPage=0;
const versionLabel=request=>request.kind==='runtime'?(runtimes.find(r=>r.id===request.runtime)?.label||request.runtime):request.name.trim();
function versionForm(compact=false){return `<form id="version-form" class="version-form ${compact?'compact':''}"><div class="version-fields"><label>Look for<select id="version-kind" name="kind"><option value="package" ${versionRequest.kind==='package'?'selected':''}>Package</option><option value="runtime" ${versionRequest.kind==='runtime'?'selected':''}>Language / runtime</option></select></label>${versionRequest.kind==='runtime'?`<label>Language / runtime<select id="version-runtime" name="runtime">${runtimes.map(r=>`<option value="${r.id}" ${r.id===versionRequest.runtime?'selected':''}>${esc(r.label)}</option>`).join('')}</select></label>`:`<label>Package name or URL<input id="version-name" name="name" list="package-suggestions" placeholder="e.g. lodash, openssl, @scope/package" value="${esc(versionRequest.name)}" autocomplete="off"><datalist id="package-suggestions">${[...new Set(model.components.map(c=>c.group?`${c.group}/${c.name}`:c.name))].sort().slice(0,1000).map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist></label><label>Name match<select id="version-name-match" name="match"><option value="exact" ${versionRequest.match==='exact'?'selected':''}>Exact name</option><option value="contains" ${versionRequest.match==='contains'?'selected':''}>Contains text</option></select></label>`}<label>Version condition<select id="version-operator" name="operator">${operators.map(o=>`<option value="${o.id}" ${versionRequest.operator===o.id?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label><label>Threshold version<input id="version-target" name="target" value="${esc(versionRequest.target)}" placeholder="e.g. 3.11" ${versionRequest.operator==='any'?'disabled':''} autocomplete="off" aria-describedby="version-help"></label><button class="button primary" type="submit">Check versions →</button></div></form>`;}
function versionShortcut(){return panel('Find a package or runtime version',`<p id="version-help" class="section-note">Quickly check “Python ≥ 3.11” or “lodash &lt; 4.17.21” using the current inventory.</p>${versionForm(true)}`,`<a href="#versions" class="text-link">Version search ↗</a>`);}
function versionSearch(){return panel('Check the inventory',`${versionForm()}<div class="version-presets"><span>Quick checks</span><button type="button" data-version-preset="python">Python ≥ 3.11</button><button type="button" data-version-preset="node">Node.js &lt; 20</button><button type="button" data-version-preset="java">Java ≥ 17</button><button type="button" data-version-preset="lodash">lodash &lt; 4.17.21</button></div><p id="version-help" class="footnote">Searches the components actually recorded in this SBOM. Runtime matching uses common component names; package ecosystems alone do not establish the language version. A record without a dependency path does not establish application usage.</p>`)+`<div id="version-output" aria-live="polite">${versionHasRun?versionResults():'<div class="panel empty">Choose a package or runtime and select “Check versions.”</div>'}</div>`;}
function versionResults(){const result=searchVersions(model,versionRequest);if(result.error)return `<div class="panel"><p role="alert" class="risk">${esc(result.error)}</p></div>`;const expression=`${versionLabel(versionRequest)} ${operators.find(o=>o.id===versionRequest.operator)?.symbol||''} ${versionRequest.operator==='any'?'(any version)':versionRequest.target}`;const label=versionRequest.kind==='runtime'?'runtime name':'package';let summary;if(!result.rows.length)summary=`No ${label} records found for ${versionLabel(versionRequest)}. The SBOM may omit this component; this does not prove the application does not use it.`;else if(result.matched)summary=`${result.matched} of ${result.rows.length} recorded component(s) match ${expression}.${result.unknown?` ${result.unknown} could not be compared and require review.`:''}`;else summary=`No comparable records match ${expression}.${result.unknown?` ${result.unknown} record(s) could not be compared; the result is incomplete.`:` ${result.rows.length} record(s) have other versions.`}`;const rows=result.rows.filter(r=>r.status===versionTab);versionPage=Math.min(versionPage,Math.max(0,Math.ceil(rows.length/50)-1));return stats([['Records found',result.rows.length,'Matching package or runtime names','⌕'],['Condition matched',result.matched,esc(expression),'✓'],['Other versions',result.other,'Do not match this condition','⇄'],['Cannot compare',result.unknown,'Missing or unsupported version','?']])+panel(`Results for ${esc(expression)}`,`<p class="version-summary ${result.unknown?'needs-review':''}">${esc(summary)}</p><div class="version-tabs" role="group" aria-label="Filter version results">${[['match','Matches',result.matched],['other','Other versions',result.other],['unknown','Cannot compare',result.unknown]].map(([id,title,n])=>`<button class="${versionTab===id?'selected':''}" data-version-tab="${id}" aria-pressed="${versionTab===id}">${title} <span>${n}</span></button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Component</th><th>Recorded version</th><th>Comparison</th><th>Dependency evidence</th><th>Explore</th></tr></thead><tbody>${rows.slice(versionPage*50,versionPage*50+50).map(r=>{const c=r.component,path=model.root?pathTo({...model,roots:[model.root]},c.id):[];return `<tr><td>${link(c)}<small>${esc(c.purl||c.id)}</small></td><td><strong>${esc(r.version||'Not supplied')}</strong><small>${esc(r.source)}</small></td><td>${tag(r.status==='match'?'Matches':r.status==='other'?'Other version':'Cannot compare',r.status==='unknown'?'medium':r.status==='other'?'unknown':'')}<small>${esc(r.reason)}</small></td><td>${path.length?`<span>${path.length===1?'Application root':path.length===2?'Direct dependency':'Transitive dependency'}</span><small>${esc(path.map(id=>model.map.get(id)?.name||id).join(' → '))}</small>`:'<span class="subtle">No path from application root</span>'}</td><td><button class="text-link quiet" data-version-graph="${esc(c.id)}">Graph →</button></td></tr>`}).join('')||`<tr><td colspan="5" class="empty">${!result.rows.length?'No matching names recorded.':versionTab==='unknown'?'No records need manual comparison.':versionTab==='other'?'No other comparable versions.':'No records match the version condition.'}</td></tr>`}</tbody></table></div><div class="pager"><span>${rows.length} ${versionTab==='match'?'matching':versionTab==='other'?'other':'uncomparable'} record(s) · page ${versionPage+1} of ${Math.max(1,Math.ceil(rows.length/50))}</span><button class="button" id="version-prev" ${versionPage===0?'disabled':''}>Previous</button><button class="button" id="version-next" ${(versionPage+1)*50>=rows.length?'disabled':''}>Next</button><button class="button" id="version-csv" ${!result.rows.length?'disabled':''}>↓ Export all results</button></div><details><summary>How versions are compared</summary><p class="footnote">Numeric segments are compared as numbers: 3.10 is above 3.9. Missing trailing segments count as zero, so 3.11 equals 3.11.0. Recognized SemVer prereleases (alpha, beta, rc, pre, preview, dev, next, canary, snapshot) sort before the corresponding stable release; build metadata does not affect order. Leading v is accepted; Go runtime checks also accept go prefixes. Java runtime checks treat the legacy 1.8 style as Java 8. Ranges, distro revisions, and other ecosystem-specific formats require manual comparison. Package URL versions are used only when the component version is absent.</p></details>`,`<span class="subtle">${isSample?'Sample data · ':''}Document evidence</span>`);}
function readVersionForm(){const f=$('#version-form');if(!f)return;const data=new FormData(f);versionRequest={...versionRequest,...Object.fromEntries(data.entries())};}
function runVersionCheck(){readVersionForm();versionHasRun=true;versionPage=0;versionTab='match';if(location.hash!=='#versions')location.hash='versions';else render();}
function bindVersionSearch(){const f=$('#version-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();runVersionCheck()};const invalidate=()=>{versionHasRun=false;const out=$('#version-output');if(out)out.innerHTML='<div class="panel empty">Search changed. Select “Check versions” to update results.</div>'};f.oninput=invalidate;f.onchange=invalidate;$('#version-kind').addEventListener('change',()=>{readVersionForm();versionHasRun=false;render()});$('#version-operator').addEventListener('change',()=>{$('#version-target').disabled=$('#version-operator').value==='any'});document.querySelectorAll('[data-version-preset]').forEach(b=>b.onclick=()=>{const p=b.dataset.versionPreset;versionRequest=p==='lodash'?defaultVersionRequest():{kind:'runtime',runtime:p,name:'',match:'exact',operator:p==='node'?'lt':'gte',target:p==='python'?'3.11':p==='node'?'20':'17'};versionHasRun=true;versionTab='match';versionPage=0;render()});document.querySelectorAll('[data-version-tab]').forEach(b=>b.onclick=()=>{versionTab=b.dataset.versionTab;versionPage=0;render()});document.querySelectorAll('[data-version-graph]').forEach(b=>b.onclick=()=>{focus=b.dataset.versionGraph;graphMode='impact';location.hash='graph'});$('#version-prev')?.addEventListener('click',()=>{versionPage--;render()});$('#version-next')?.addEventListener('click',()=>{versionPage++;render()});$('#version-csv')?.addEventListener('click',()=>{const results=searchVersions(model,versionRequest);csv(results.rows.map(r=>({query:versionLabel(versionRequest),condition:versionRequest.operator,target:versionRequest.operator==='any'?'':versionRequest.target,status:r.status,name:r.component.name,version:r.version,versionSource:r.source,reason:r.reason,purl:r.component.purl,reference:r.component.id})),'version-search.csv')});}

const enterprise=createEnterprise({
  onChange:()=>render(),
  openDialog:html=>{$('#detail-body').innerHTML=html;$('#details').showModal();},
  inspectSbom:(bom,filename,context)=>{
    model=normalize(bom,filename);isSample=true;documentContext=context;baseline=null;focus='';query='';licenseFilter='';riskFilter='';page=0;
    versionRequest={...defaultVersionRequest(),name:'',target:''};versionHasRun=false;
    $('#details').close();notice('Simulated deployed artifact · '+context);location.hash='overview';render();
  },
});
const views={overview:['◫','Overview','Understand what’s inside your software.'],components:['▤','Components','Search, filter, and inspect your software inventory.'],versions:['⌕','Version search','Find recorded runtimes and packages above or below a version.'],graph:['⌘','Dependency graph','Follow dependencies and explore their downstream impact.'],licenses:['◉','Licenses','Explore declared licenses and where review may be needed.'],findings:['◇','Findings','Inspect vulnerability and VEX information supplied in this SBOM.'],quality:['☑','Data quality','Find gaps that limit the usefulness of your inventory.'],compare:['⇄','Compare releases','See what changed between two software inventories.'],source:['{ }','Source document','Inspect the original SBOM and its document metadata.']};
const tag=(t,cls='')=>`<span class="tag ${esc(cls)}">${esc(t)}</span>`;
const link=c=>`<button class="component-link" data-id="${esc(c.id)}">${esc(c.name)}</button>`;
const panel=(title,body,right='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${right}</div>${body}</section>`;
const counts=arr=>arr.reduce((m,x)=>(m[x]=(m[x]||0)+1,m),{});
const stats=items=>`<div class="stats">${items.map(([label,n,sub,icon])=>`<div class="stat"><span class="stat-label">${label}</span><span class="stat-icon">${icon}</span><div class="stat-num">${n}</div><small>${sub}</small></div>`).join('')}</div>`;
const severityFor=id=>model.vulns.filter(v=>v.refs.includes(id));
const licenseGroups=()=>counts(model.components.flatMap(c=>c.licenses.length?c.licenses:['Unknown']));
const policy=l=>l==='Unknown'?'Unknown':/\b(AGPL|GPL|LGPL|MPL|EPL|CDDL)\b/.test(l)?'Review copyleft':'Declared';
function notice(s){$('#notice').textContent=s;$('#notice').hidden=!s;}
function render(){
  view=location.hash.slice(1)||'applications';
  if(!views[view]&&!enterpriseViews[view])view='applications';
  const isFleet=!!enterpriseViews[view];
  const navItem=([id,[icon,title]])=>`<a href="#${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${title}</a>`;
  $('#nav').innerHTML=Object.entries(enterpriseViews).map(navItem).join('')+'<div class="fleet-nav-label">SBOM DOCUMENT</div>'+Object.entries(views).map(navItem).join('');
  const definition=(isFleet?enterpriseViews:views)[view];
  $('#page-title').textContent=definition[1];$('#page-description').textContent=definition[2];
  $('#doc-name').textContent=isFleet?'Application portfolio':model.name;
  $('#sample-badge').textContent=isFleet?'Simulated data':documentContext?'Simulated artifact SBOM':isSample?'Sample data':model.format;
  $('.page-heading .eyebrow').textContent=isFleet?'APPLICATION → BUILD → DEPLOYMENT':'SOFTWARE SUPPLY CHAIN · EXPLORER';
  $('#export').textContent=isFleet?'↓ Export view':'↓ Export report';
  document.body.classList.toggle('fleet-mode',isFleet);
  $('#content').innerHTML=isFleet?enterprise.render(view):({overview,components,versions:versionSearch,graph,licenses,findings,quality,compare:comparison,source})[view]();
  if(isFleet)enterprise.bind(view);else bind();
}

function overview(){const n=model.components.length,ls=licenseGroups(),direct=(model.outgoing.get(model.root)||[]).filter(id=>model.map.has(id)).length;const known=n-model.missing('licenses'),pct=n?Math.round(known/n*100):0;const severities=counts(model.vulns.map(v=>v.severity));return versionShortcut()+stats([['Components',n,`${model.map.size} distinct references`,'⬡'],['Dependency links',model.edges.length,`${direct} direct dependencies of root`,'⌘'],['License coverage',pct+'%',`${model.missing('licenses')} components unspecified`,'◉'],['Supplied findings',model.vulns.length,model.vulns.length?'Embedded records · not a live scan':'No findings supplied','◇']])+`<div class="grid">`+panel('Your software, at a glance',`<p class="summary"><strong>${esc(model.name)}${model.version?' '+esc(model.version):''}</strong> contains <strong>${n} components</strong> connected by <strong>${model.edges.length} dependency links</strong>. ${direct?`${direct} dependencies are attached directly to the application root.`:'The document does not supply direct application-root dependencies.'} ${known} components have declared license information. ${model.vulns.length?`The document supplies ${model.vulns.length} vulnerability records; their presence and applicability require review.`:'No vulnerability records are supplied. This does not establish that the components are vulnerability-free.'}</p><div class="callout ${model.missing('licenses')?'warning':''}">${model.missing('licenses')?`${model.missing('licenses')} component(s) have no license information. Review the license inventory before making compliance decisions.`:'All listed components have license information. Expressions and obligations still need review.'}</div><div class="meta"><div><label>FORMAT</label><span>${esc(model.format)} ${esc(model.spec)}</span></div><div><label>GENERATED</label><span>${esc(model.timestamp||'Not supplied')}</span></div><div><label>FILE</label><span>${esc(model.filename)}</span></div><div><label>ANALYSIS</label><span>Local · document evidence only</span></div></div>`,`<a href="#source" class="text-link">View metadata ↗</a>`)+panel('License distribution',Object.entries(ls).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([l,c])=>`<div class="bar-row"><div class="bar-label"><span>${esc(l)}</span><span>${c}</span></div><div class="bar"><i style="width:${n?c/n*100:0}%"></i></div></div>`).join('')||'<p class="empty">No components supplied.</p>',`<a href="#licenses" class="text-link">Explore licenses ↗</a>`)+`</div><div class="grid">`+panel('Dependency preview',`<div class="mini-graph">${graphSVG(model.components.slice(0,12),false)}</div><p class="footnote">Preview of up to 12 components. Arrows point from a component to its dependency.</p>`,`<a href="#graph" class="text-link">Open graph ↗</a>`)+panel('Finding breakdown',`<div class="chart-flex"><div class="donut" style="background:conic-gradient(${model.vulns.length?'#c67b65 0deg '+((severities.high||0)+(severities.critical||0))/model.vulns.length*360+'deg,#dab477 0deg 360deg':'#e5ebdf 0deg 360deg'})"><b>${model.vulns.length}</b></div><div class="legend-list">${['critical','high','medium','low','unknown'].map((s,i)=>`<div class="legend-row"><span><i style="background:${['#9d463d','#c67b65','#dab477','#7c9dba','#b9c2b1'][i]}"></i>${s[0].toUpperCase()+s.slice(1)}</span><span>${severities[s]||0}</span></div>`).join('')}</div></div><p class="footnote">${isSample?'Illustrative findings in sample data. ':''}No external vulnerability database has been queried.</p>`,`<a href="#findings" class="text-link">Review findings ↗</a>`)+`</div>`+panel('Most connected components',componentTable([...model.components].sort((a,b)=>(model.incoming.get(b.id)||[]).length-(model.incoming.get(a.id)||[]).length).slice(0,5)),`<a href="#components" class="text-link">All components ↗</a>`);}
function componentTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Component</th><th>Version</th><th>License</th><th>Dependencies</th><th>Used by</th><th>Findings</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${link(c)}<small>${esc(c.purl||c.type)}</small></td><td>${esc(c.version||'—')}</td><td>${c.licenses.map(l=>tag(l)).join(' ')||tag('Unknown','unknown')}</td><td>${(model.outgoing.get(c.id)||[]).length}</td><td>${(model.incoming.get(c.id)||[]).length}</td><td>${severityFor(c.id).length?tag(severityFor(c.id).length+' supplied','high'):'<span class="subtle">None supplied</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching components.</td></tr>'}</tbody></table></div>`;}
function filtered(){return model.components.filter(c=>`${c.name} ${c.version} ${c.purl} ${c.group} ${c.id}`.toLowerCase().includes(query.toLowerCase())&&(!licenseFilter||(licenseFilter==='Unknown'?!c.licenses.length:c.licenses.includes(licenseFilter)))&&(!riskFilter||(riskFilter==='findings'?severityFor(c.id).length:riskFilter==='missing-purl'?!c.purl:!c.licenses.length))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):(model.incoming.get(b.id)||[]).length-(model.incoming.get(a.id)||[]).length);}
function components(){const rows=filtered();page=Math.min(page,Math.max(0,Math.ceil(rows.length/50)-1));return panel('Component inventory',`<div class="toolbar"><input id="search" aria-label="Search components" placeholder="Search names, versions, package URLs…" value="${esc(query)}"><select id="license-filter" aria-label="Filter license"><option value="">All licenses</option>${Object.keys(licenseGroups()).sort().map(l=>`<option ${l===licenseFilter?'selected':''}>${esc(l)}</option>`).join('')}</select><select id="risk-filter" aria-label="Filter analysis"><option value="">All components</option><option value="findings" ${riskFilter==='findings'?'selected':''}>With supplied findings</option><option value="missing-license" ${riskFilter==='missing-license'?'selected':''}>Missing license</option><option value="missing-purl" ${riskFilter==='missing-purl'?'selected':''}>Missing package URL</option></select><select id="sort" aria-label="Sort components"><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="used" ${sort==='used'?'selected':''}>Most used</option></select><button class="button" id="csv">↓ CSV</button></div><div id="table-results">${componentTable(rows.slice(page*50,page*50+50))}<div class="pager"><span>${rows.length} results · page ${page+1} of ${Math.max(1,Math.ceil(rows.length/50))}</span><button id="prev" class="button" ${page===0?'disabled':''}>Previous</button><button id="next" class="button" ${(page+1)*50>=rows.length?'disabled':''}>Next</button></div></div>`);}
function licenses(){const ls=licenseGroups();return `<p class="section-note">License expressions are preserved as supplied. Copyleft labels are review hints, not legal conclusions; complex expressions, exceptions, and custom licenses need individual assessment.</p>`+stats([['License expressions',Object.keys(ls).filter(x=>x!=='Unknown').length,'Distinct supplied expressions','◉'],['Missing licenses',model.missing('licenses'),'Information not supplied','?'],['Copyleft review',model.components.filter(c=>c.licenses.some(l=>policy(l)==='Review copyleft')).length,'Components with review hints','◇'],['With license data',model.components.length-model.missing('licenses'),'Components with declarations','✓']])+panel('License inventory',`<div class="license-cards">${Object.entries(ls).sort((a,b)=>b[1]-a[1]).map(([l,c])=>`<div class="license-card"><h3>${esc(l)}</h3><div class="license-count">${c} <span class="subtle">component${c===1?'':'s'}</span></div>${tag(policy(l),policy(l)==='Review copyleft'?'medium':l==='Unknown'?'unknown':'')}<p><button class="text-link quiet" data-license="${esc(l)}">View components →</button></p></div>`).join('')||'<p class="empty">No license data supplied.</p>'}</div>`);}
function findings(){return `<p class="section-note">Only findings embedded in the imported SBOM are shown. Severity, score, and VEX state come from the document. This viewer does not perform a live vulnerability scan.</p>`+panel('Supplied vulnerability records',model.vulns.length?`<div class="table-wrap"><table><thead><tr><th>Finding</th><th>Severity / score</th><th>Affected components</th><th>VEX state</th><th>Details</th></tr></thead><tbody>${model.vulns.map((v,i)=>`<tr><td><strong>${esc(v.id)}</strong><small>${esc(v.source||'Source not supplied')}</small></td><td>${tag(v.severity,v.severity)} ${esc(v.score??'')}</td><td>${v.refs.map(id=>model.map.has(id)?link(model.map.get(id)):`<span class="subtle">${esc(id)} (unresolved)</span>`).join('<br>')||'No affected references supplied'}</td><td>${tag(v.state,'unknown')}</td><td><button class="text-link quiet" data-finding="${i}">Inspect →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No vulnerability findings supplied.<br>This is not evidence that the software has no vulnerabilities.</div>');}
function quality(){const n=model.components.length,coverage=k=>n?Math.round((n-model.missing(k))/n*100):0;const issues=[['Missing versions',model.missing('version'),'Version gaps prevent precise component and vulnerability matching.','version'],['Missing package URLs',model.missing('purl'),'Package URLs help identify ecosystem, package, and version.','purl'],['Missing license information',model.missing('licenses'),'Undeclared licenses limit compliance review.','licenses'],['Missing hashes',model.components.filter(c=>!c.hashes.length).length,'Checksums provide evidence of exact component artifacts.','hashes'],['Duplicate references',model.duplicateRefs,'Repeated identifiers make dependency resolution ambiguous.','duplicates'],['Unresolved dependency links',model.unresolved.length,'One or both endpoints do not resolve to a supplied component.','unresolved'],['Cycle back edges',model.cycles.length,'Dependency cycles can complicate traversal and remediation.','cycles']];return stats([['Version coverage',coverage('version')+'%','Of supplied components','✓'],['Package URL coverage',coverage('purl')+'%','Of supplied components','⬡'],['License coverage',coverage('licenses')+'%','Of supplied components','◉'],['Unresolved links',model.unresolved.length,'Dependency endpoint gaps','⌘']])+panel('Inventory checks',issues.map(([t,n,d,key])=>`<div class="issue"><div><h3 style="margin:0">${t}</h3><p>${d}</p>${n?`<details><summary>Inspect ${n} affected record(s)</summary>${key==='unresolved'||key==='cycles'?`<pre>${esc(JSON.stringify(model[key],null,2))}</pre>`:`<div class="detail-list">${model.components.filter(c=>key==='duplicates'?model.components.filter(x=>x.id===c.id).length>1:key==='licenses'?!c.licenses.length:key==='hashes'?!c.hashes.length:!c[key]).slice(0,100).map(c=>link(c)).join(' ')}</div>`}</details>`:''}</div>${tag(n===0?'Complete':n+' to review',n?'medium':'')}</div>`).join('')+`<p class="footnote">Structural checks cover component metadata and relationships. They do not replace full schema validation or verify inventory completeness against the software artifact. Cycle evidence is limited to the first 100 back edges.</p>`);}
function comparison(){const rows=baseline?compare(model,baseline):[];return panel('Compare with a previous SBOM',`<p class="section-note">Current: <strong>${esc(model.filename)}</strong>${baseline?` · Baseline: <strong>${esc(baseline.filename)}</strong>`:''}. Match by package URL without its version, falling back to group, name, and type. Multiple versions are compared together; package URL qualifiers are preserved.</p><div class="toolbar"><button class="button primary" id="load-baseline">＋ Open baseline SBOM</button>${baseline?'<button class="button" id="diff-csv">↓ Export changes</button><button class="button" id="clear-baseline">Clear baseline</button>':''}</div>${baseline?stats([['Added',rows.filter(r=>r.status==='Added').length,'New component identities','＋'],['Removed',rows.filter(r=>r.status==='Removed').length,'Absent in current inventory','−'],['Version changes',rows.filter(r=>r.status==='Changed').length,'Different version sets','⇄'],['License changes',rows.filter(r=>r.status==='License changed').length,'Same-version declaration changes','◉']])+`<div class="table-wrap"><table><thead><tr><th>Change</th><th>Component</th><th>Baseline</th><th>Current</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${tag(r.status,r.status==='Removed'?'medium':'')}</td><td>${esc(r.name)}</td><td>${esc(r.before)}</td><td>${esc(r.after)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No component version or license changes found.</td></tr>'}</tbody></table></div><p class="footnote">Comparison covers component identities, version sets, and same-version license changes. Dependency and finding changes are not compared.</p>`:'<div class="empty">Open a baseline to see added, removed, updated,<br>and license-changed components.</div>'}`);}
function source(){return panel('Original document',`<div class="toolbar"><span class="subtle">${esc(model.filename)} · ${esc(model.format)} ${esc(model.spec)}</span><button class="button" id="download-json">↓ Download JSON</button></div><pre>${esc(JSON.stringify(model.raw,null,2))}</pre>`);}
function graphNodes(){let rows=model.components;if(focus){const ids=new Set([focus,...(graphMode==='direct'?(model.outgoing.get(focus)||[]):closure(model,focus,graphMode==='impact'?'incoming':'outgoing'))]);rows=rows.filter(c=>ids.has(c.id));}else if(graphMode==='direct'){const ids=new Set([...model.roots,...model.roots.flatMap(id=>model.outgoing.get(id)||[])]);rows=rows.filter(c=>ids.has(c.id));}return [...new Map(rows.map(c=>[c.id,c])).values()];}
function graph(){const rows=graphNodes();return panel('Dependency map',`<div class="toolbar"><select id="graph-focus" aria-label="Focus component"><option value="">All components</option>${[...model.map.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${esc(c.id)}" ${focus===c.id?'selected':''}>${esc(c.name)} ${esc(c.version)}</option>`).join('')}</select><select id="graph-mode" aria-label="Graph traversal"><option value="all" ${graphMode==='all'?'selected':''}>All dependencies</option><option value="direct" ${graphMode==='direct'?'selected':''}>Root + direct dependencies</option><option value="impact" ${graphMode==='impact'?'selected':''}>Reverse impact (select component)</option></select><button id="zoom-out" class="button" aria-label="Zoom out">−</button><button id="zoom-in" class="button" aria-label="Zoom in">＋</button><button id="reset-graph" class="button">Fit graph</button></div><div class="graph-box">${graphSVG(rows.slice(0,120),true)}</div><div class="graph-legend"><span><i></i>Root</span><span><i class="dependency"></i>Dependency</span><span><i class="risky"></i>Supplied finding</span></div><p class="footnote">${rows.length>120?`Showing the first 120 of ${rows.length} nodes. Focus on a component to explore a smaller subgraph. `:`${rows.length} nodes shown. `}Click a node to inspect it. Drag the canvas to pan; use the zoom buttons or mouse wheel. Arrows point to dependencies. ${graphMode==='impact'&&!focus?'Choose a component to explore reverse impact.':''}</p>`);}
function graphSVG(rows,interactive){const width=1000,nodeW=140,nodeH=48,pad=35,positions=new Map(),levels=new Map();rows.forEach(c=>{let d=model.depths.get(c.id)??0;if(focus)d=c.id===focus?0:1;d=Math.min(d,6);if(!levels.has(d))levels.set(d,[]);levels.get(d).push(c);});const cols=[...levels.keys()].sort((a,b)=>a-b);const height=Math.max(260,...[...levels.values()].map(x=>x.length*75+70));cols.forEach((d,col)=>{const arr=levels.get(d);arr.forEach((c,i)=>positions.set(c.id,{x:pad+col*(width-pad*2-nodeW)/Math.max(1,cols.length-1),y:height/2-(arr.length-1)*75/2+i*75-nodeH/2}));});return `<svg ${interactive?'id="graph-svg"':''} viewBox="0 0 ${width} ${height}" role="img" aria-label="Dependency graph" data-width="${width}" data-height="${height}"><defs><marker id="arrow-${interactive?'full':'mini'}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#9bb38d"/></marker></defs>${model.edges.filter(([a,b])=>positions.has(a)&&positions.has(b)).map(([a,b])=>{const p=positions.get(a),q=positions.get(b);return `<path class="graph-edge" marker-end="url(#arrow-${interactive?'full':'mini'})" d="M${p.x+nodeW} ${p.y+24} C${p.x+nodeW+45} ${p.y+24},${q.x-45} ${q.y+24},${q.x} ${q.y+24}"/>`;}).join('')}${rows.map(c=>{const p=positions.get(c.id);return `<g class="graph-node ${model.roots.includes(c.id)?'root':''} ${severityFor(c.id).length?'risky':''}" transform="translate(${p.x},${p.y})" data-id="${esc(c.id)}" tabindex="0" role="button" aria-label="Inspect ${esc(c.name)}"><rect width="${nodeW}" height="${nodeH}" rx="6"/><text x="12" y="21">${esc(c.name.length>18?c.name.slice(0,17)+'…':c.name)}</text><text class="version" x="12" y="36">${esc(c.version||'Version unspecified')}</text><title>${esc(c.name+' '+c.version)}</title></g>`;}).join('')}</svg>`;}
function detail(id){const c=model.map.get(id);if(!c)return;const deps=model.outgoing.get(id)||[],parents=model.incoming.get(id)||[],path=pathTo(model,id);$('#detail-body').innerHTML=`<span class="eyebrow">COMPONENT DETAILS</span><h2 style="margin-top:12px">${esc(c.name)}</h2><p class="subtle">${esc(c.description||c.type)}</p><div class="meta">${[['Version',c.version||'Not supplied'],['License',c.licenses.join(' OR ')||'Not supplied'],['Reference',c.id],['Supplier',c.supplier||'Not supplied']].map(([k,v])=>`<div><label>${k.toUpperCase()}</label><span>${esc(v)}</span></div>`).join('')}</div><h3>Package URL</h3><pre>${esc(c.purl||'Not supplied')}</pre><h3>Dependency path</h3><p class="footnote">${path.length?path.map(id=>esc(model.map.get(id)?.name||id)).join(' → '):'No path from a supplied root; the graph may be cyclic or disconnected.'}</p><h3>Depends on · ${deps.length}</h3><div class="detail-list">${deps.map(id=>model.map.has(id)?link(model.map.get(id)):esc(id)+' (unresolved)').join(' ')||'<span class="subtle">None supplied</span>'}</div><h3>Used by · ${parents.length} direct / ${closure(model,id,'incoming').length} transitive</h3><div class="detail-list">${parents.map(id=>model.map.has(id)?link(model.map.get(id)):esc(id)+' (unresolved)').join(' ')||'<span class="subtle">None supplied</span>'}</div><h3>Supplied findings</h3>${severityFor(id).map(v=>`<p>${tag(v.severity,v.severity)} ${esc(v.id)} · ${esc(v.state)}</p>`).join('')||'<p class="subtle">No records supplied for this component.</p>'}<button id="focus-detail" class="button" data-focus="${esc(id)}">Explore in graph →</button><details><summary>Original component record</summary><pre>${esc(JSON.stringify(c.raw,null,2))}</pre></details>`;$('#details').showModal();bindDetails();}
function bindDetails(){bindIds($('#detail-body'));$('#focus-detail')?.addEventListener('click',e=>{focus=e.currentTarget.dataset.focus;graphMode='all';$('#details').close();location.hash='graph';render();});}
function bindIds(root){root.querySelectorAll('[data-id]').forEach(el=>{el.onclick=e=>{e.stopPropagation();detail(el.dataset.id)};if(el.tagName.toLowerCase()==='g')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(el.dataset.id);}};});}
function bind(){bindIds($('#content'));bindVersionSearch();$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});for(const [id,fn] of [['license-filter',v=>licenseFilter=v],['risk-filter',v=>riskFilter=v],['sort',v=>sort=v]])$('#'+id)?.addEventListener('change',e=>{fn(e.target.value);page=0;render()});$('#prev')?.addEventListener('click',()=>{page--;render()});$('#next')?.addEventListener('click',()=>{page++;render()});$('#csv')?.addEventListener('click',()=>csv(filtered().map(c=>({name:c.name,version:c.version,purl:c.purl,licenses:c.licenses.join(' OR '),dependencies:(model.outgoing.get(c.id)||[]).length,usedBy:(model.incoming.get(c.id)||[]).length,suppliedFindings:severityFor(c.id).length})),'components.csv'));document.querySelectorAll('[data-license]').forEach(e=>e.onclick=()=>{licenseFilter=e.dataset.license;query='';riskFilter='';page=0;location.hash='components'});document.querySelectorAll('[data-finding]').forEach(e=>e.onclick=()=>{const v=model.vulns[+e.dataset.finding];$('#detail-body').innerHTML=`<h2>${esc(v.id)}</h2><p>${tag(v.severity,v.severity)} · Score ${esc(v.score??'not supplied')}</p><p>${esc(v.description||'No description supplied.')}</p><p>VEX state: ${esc(v.state)}<br>Response: ${esc(v.response||'Not supplied')}</p><details><summary>Original vulnerability record</summary><pre>${esc(JSON.stringify(v.raw,null,2))}</pre></details>`;$('#details').showModal()});$('#load-baseline')?.addEventListener('click',()=>$('#baseline').click());$('#clear-baseline')?.addEventListener('click',()=>{baseline=null;render()});$('#diff-csv')?.addEventListener('click',()=>csv(compare(model,baseline),'changes.csv'));$('#download-json')?.addEventListener('click',()=>download(JSON.stringify(model.raw,null,2),'sbom.json','application/json'));$('#graph-focus')?.addEventListener('change',e=>{focus=e.target.value;render()});$('#graph-mode')?.addEventListener('change',e=>{graphMode=e.target.value;render()});setupGraph();}
function setupGraph(){const svg=$('#graph-svg');if(!svg)return;const w=+svg.dataset.width,h=+svg.dataset.height;let box=[0,0,w,h],drag=null,moved=false;const set=()=>svg.setAttribute('viewBox',box.join(' '));const zoom=f=>{const nw=box[2]*f,nh=box[3]*f;if(nw<100||nw>10000)return;box=[box[0]+(box[2]-nw)/2,box[1]+(box[3]-nh)/2,nw,nh];set()};$('#zoom-in').onclick=()=>zoom(.8);$('#zoom-out').onclick=()=>zoom(1.25);$('#reset-graph').onclick=()=>{box=[0,0,w,h];set()};svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.88)},{passive:false});svg.onpointerdown=e=>{if(e.target.closest('[data-id]'))return;drag=[e.clientX,e.clientY,...box];svg.setPointerCapture(e.pointerId);moved=false};svg.onpointermove=e=>{if(!drag)return;const r=svg.getBoundingClientRect(),scale=Math.max(drag[4]/r.width,drag[5]/r.height);box=[drag[2]-(e.clientX-drag[0])*scale,drag[3]-(e.clientY-drag[1])*scale,drag[4],drag[5]];set();moved=true};svg.onpointerup=()=>drag=null;svg.onpointercancel=()=>drag=null;}
function download(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows,name){if(!rows.length){notice('No rows to export.');return}const keys=Object.keys(rows[0]);const cell=x=>'"'+String(x??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';download([keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),name,'text/csv')}
function report(){const ls=licenseGroups();download(`# SBOM analysis: ${model.name}\n\n${isSample?'SAMPLE DATA — illustrative only.\n\n':''}File: ${model.filename}\nFormat: ${model.format} ${model.spec}\nGenerated: ${model.timestamp||'Not supplied'}\n\n## Inventory\n\n- Components: ${model.components.length}\n- Dependency links: ${model.edges.length}\n- Unresolved links: ${model.unresolved.length}\n- Cycle back edges (up to 100): ${model.cycles.length}\n- Missing versions: ${model.missing('version')}\n- Missing package URLs: ${model.missing('purl')}\n- Missing licenses: ${model.missing('licenses')}\n\n## Licenses\n\n${Object.entries(ls).map(([l,n])=>`- ${l}: ${n}`).join('\n')}\n\n## Supplied vulnerability records\n\n${model.vulns.map(v=>`- ${v.id}: ${v.severity}; score ${v.score??'not supplied'}; VEX ${v.state}; affects ${v.refs.join(', ')}`).join('\n')||'No findings supplied.'}\n\nNo external vulnerability scan was performed. Structural analysis does not establish inventory completeness or legal compliance.\n\n## Components\n\n${model.components.map(c=>`- ${c.name} ${c.version||'(version unspecified)'} — ${c.licenses.join(' OR ')||'license unspecified'}`).join('\n')}\n`,'sbom-analysis.md','text/markdown')}
async function load(file,asBaseline=false){if(!file)return;if(file.size>32*1024*1024){notice('File exceeds the 32 MB limit. Please use a smaller SBOM.');return}try{const parsed=normalize(JSON.parse(await file.text()),file.name);if(asBaseline){baseline=parsed;location.hash='compare'}else{model=parsed;isSample=false;documentContext='';baseline=null;versionRequest={...defaultVersionRequest(),name:'',target:''};versionHasRun=false;focus='';query='';licenseFilter='';riskFilter='';page=0}if(!asBaseline&&enterpriseViews[view])location.hash='overview';notice(parsed.duplicateRefs?'Duplicate references found. Dependency details resolve to the first occurrence; review Data quality.':'');render();}catch(e){notice('Unable to open SBOM: '+e.message)}}
$('#upload').onclick=()=>$('#file').click();$('#file').onchange=e=>{load(e.target.files[0]);e.target.value=''};$('#baseline').onchange=e=>{load(e.target.files[0],true);e.target.value=''};$('#export').onclick=()=>enterpriseViews[view]?enterprise.export():report();$('#sample').onclick=()=>{model=normalize(sample(),'example.cdx.json');isSample=true;documentContext='';baseline=null;versionRequest=defaultVersionRequest();versionHasRun=true;versionTab='match';versionPage=0;focus='';query='';licenseFilter='';riskFilter='';page=0;notice('');location.hash='overview';render()};$('#close-detail').onclick=()=>$('#details').close();$('#details').onclick=e=>{if(e.target===$('#details')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};window.onhashchange=render;document.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('drop-target')});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('drop-target')});document.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('drop-target');load(e.dataTransfer.files[0])});render();enterprise.load();
